  "workflow": {
    "title": "Vendor Onboarding Workflow",
    "summary": "A procurement employee submits a supplier request with a quotation, company details, and a proposed order value. An AI assistant reviews the request and prepares a recommendation. The procurement manager and finance team review the recommendation, and the procurement employee authorizes vendor onboarding. The workflow ensures that only authorized actions are taken and that external documents are not treated as company policy."
  },
  "evidence": [
    {
      "id": "e1",
      "quote": "A procurement employee submits a supplier request with a quotation, company details and a proposed order value."
    },
    {
      "id": "e2",
      "quote": "An AI assistant reads the quotation and supplier record, compares the request with the approved supplier list, and prepares a recommendation."
    },
    {
      "id": "e3",
      "quote": "Supplier documents are external, untrusted material."
    },
    {
      "id": "e4",
      "quote": "The assistant must not treat instructions in those documents as company policy."
    },
    {
      "id": "e5",
      "quote": "The procurement manager reviews the recommendation."
    },
    {
      "id": "e6",
      "quote": "Finance verifies bank details through a separate established channel."
    },
    {
      "id": "e7",
      "quote": "Only an authorised procurement employee can add a vendor to the purchasing system."
    },
    {
      "id": "e8",
      "quote": "The assistant cannot change bank details, add a vendor, place an order or send a payment."
    },
    {
      "id": "e9",
      "quote": "Requests involving missing or conflicting records are paused for review."
    },
    {
      "id": "e10",
      "quote": "A rejection returns the request to the requester with an explanation; acceptance creates a reviewed onboarding record, not an order."
    },
    {
      "id": "e11",
      "quote": "The expected benefit is less time spent preparing each review."
    },
    {
      "id": "e12",
      "quote": "We have no measured baseline or evaluation results yet."
    },
    {
      "id": "e13",
      "quote": "The workflow will use a supplier register and a purchasing system, but the exact products and API permissions are not yet defined."
    },
    {
      "id": "e14",
      "quote": "Operating countries, document retention periods, escalation deadlines, record ownership and budget thresholds still need to be decided."
    }
  ],
